using System.IO;using System.Net;using System.Text.Json;using ShareLink.BrowserSharing;
namespace ShareLink.BrowserShareProbe;
internal static class SessionPageHost {
 public static async Task RunAsync(string output){Directory.CreateDirectory(output);var until=DateTime.UtcNow.AddMinutes(3);foreach(var name in new[]{"one","two","receive-one","receive-two"})Directory.CreateDirectory(Path.Combine(output,name));string first=Path.Combine(output,"old-session.txt"),next=Path.Combine(output,"new-session.txt");File.WriteAllText(first,"old generated file");File.WriteAllText(next,"new generated file");BrowserFileServer? server=null;
 try{server=new BrowserFileServer([first],Path.Combine(output,"one"),true);await server.StartAsync(IPAddress.Loopback,0,CancellationToken.None);int port=server.Port;server.EnableUploads(Path.Combine(output,"receive-one"));File.WriteAllText(Path.Combine(output,"ready.json"),JsonSerializer.Serialize(new{url=$"http://127.0.0.1:{port}/"}));while(!File.Exists(Path.Combine(output,"switch"))&&DateTime.UtcNow<until&&!File.Exists(Path.Combine(output,"stop")))await Task.Delay(100);if(File.Exists(Path.Combine(output,"stop")))return;await server.DisposeAsync();server=new BrowserFileServer([next],Path.Combine(output,"two"),true);await server.StartAsync(IPAddress.Loopback,port,CancellationToken.None);server.EnableUploads(Path.Combine(output,"receive-two"));File.WriteAllText(Path.Combine(output,"switched"),"ready");while(!File.Exists(Path.Combine(output,"stop"))&&DateTime.UtcNow<until)await Task.Delay(100);
 }finally{if(server!=null)await server.DisposeAsync();}}
}
